CREATE TABLE users(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE,password TEXT,recovery TEXT,guest INTEGER NOT NULL DEFAULT 1,plan TEXT NOT NULL DEFAULT 'free',preferences TEXT NOT NULL DEFAULT '{}',created INTEGER NOT NULL);
CREATE TABLE sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE projects(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users ON DELETE CASCADE,name TEXT NOT NULL,description TEXT NOT NULL,kind TEXT NOT NULL,spec TEXT NOT NULL,created INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE INDEX projects_owner ON projects(user_id,updated DESC);
CREATE TABLE project_files(project_id TEXT NOT NULL REFERENCES projects ON DELETE CASCADE,path TEXT NOT NULL,content TEXT NOT NULL,PRIMARY KEY(project_id,path));
CREATE TABLE project_versions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects ON DELETE CASCADE,number INTEGER NOT NULL,label TEXT NOT NULL,snapshot TEXT NOT NULL,created INTEGER NOT NULL,UNIQUE(project_id,number));
CREATE TABLE project_memory(project_id TEXT PRIMARY KEY REFERENCES projects ON DELETE CASCADE,instructions TEXT NOT NULL,requirements TEXT NOT NULL,decisions TEXT NOT NULL);
CREATE TABLE ai_providers(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users ON DELETE CASCADE,slug TEXT NOT NULL,secret TEXT NOT NULL,verified INTEGER NOT NULL DEFAULT 0,UNIQUE(user_id,slug));
CREATE TABLE model_configurations(provider_id TEXT PRIMARY KEY REFERENCES ai_providers ON DELETE CASCADE,model TEXT NOT NULL,fallback INTEGER NOT NULL DEFAULT 1);
CREATE TABLE usage_records(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users ON DELETE CASCADE,provider TEXT NOT NULL,model TEXT NOT NULL,task TEXT NOT NULL,input_tokens INTEGER,output_tokens INTEGER,status TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE integrations(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users ON DELETE CASCADE,slug TEXT NOT NULL,secret TEXT NOT NULL,config TEXT NOT NULL,UNIQUE(user_id,slug));
CREATE TABLE workflows(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects ON DELETE CASCADE,name TEXT NOT NULL,trigger TEXT NOT NULL,steps TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE workflow_executions(id TEXT PRIMARY KEY,workflow_id TEXT NOT NULL REFERENCES workflows ON DELETE CASCADE,status TEXT NOT NULL,log TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE activity_logs(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users ON DELETE CASCADE,project_id TEXT REFERENCES projects ON DELETE SET NULL,action TEXT NOT NULL,detail TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX activity_owner ON activity_logs(user_id,created DESC);
CREATE TABLE records(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects ON DELETE CASCADE,page TEXT NOT NULL,data TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX records_page ON records(project_id,page);
CREATE TABLE billing_events(id TEXT PRIMARY KEY,created INTEGER NOT NULL);
